import {money,shortMoney,dateLabel,uid,metrics,groupTrades,filterTrades,calendarCells,loadState,DEMO_TODAY} from './data.js';
import {esc,icon,badge,avatar,empty,button,sparkline,lineChart,barChart,horizontalBars,metricCard} from './ui.js';
let db=loadState();
const state={role:'user',viewUserId:null,page:'overview',account:'all',range:'month',symbol:'all',session:'all',outcome:'all',query:'',calendarYear:2026,calendarMonth:9,analyticsTab:'Overview',settingsTab:'Profile',tradePage:1,sidebar:false,collapsed:false,journalQuery:'',adminQuery:'',chartMode:'equity'};
const app=document.querySelector('#app'),overlay=document.querySelector('#overlay-root');
let focusBeforeModal=null,toastTimer;
const persist=()=>{try{localStorage.setItem('structure-v1',JSON.stringify(db));}catch{toast('Your browser could not save changes. Storage may be full.');}};
const hasAdminAccess=()=>state.role==='admin';
const isAdmin=()=>hasAdminAccess()&&!state.viewUserId;
const activeUserId=()=>state.viewUserId||'u1';
const activeUser=()=>db.users.find(u=>u.id===activeUserId());
const userSettings=()=>{
 if(activeUserId()==='u1')return db;
 return db.userSettings[activeUserId()]??=( {profile:{name:activeUser().name,email:activeUser().email,timezone:'UTC',currency:'USD'},risk:{perTrade:1,dailyLoss:3,maxTrades:3},preferences:{email:true,sync:true,weekly:true}} );
};
const userEntries=()=>db.entries.filter(e=>e.userId===activeUserId());
const workspaceHref=page=>state.viewUserId?`#/admin/users/${encodeURIComponent(state.viewUserId)}/${page}`:`#/${state.role}/${page}`;
const canAccessAccount=id=>visibleAccounts().some(a=>a.id===id);
function resetWorkspaceFilters(){Object.assign(state,{account:'all',range:'month',symbol:'all',session:'all',outcome:'all',query:'',journalQuery:'',tradePage:1,analyticsTab:'Overview',settingsTab:'Profile'});}

const visibleAccounts=()=>db.accounts.filter(a=>isAdmin()||a.userId===activeUserId());
const currentTrades=(extra={})=>filterTrades(db.trades,{...state,accountIds:visibleAccounts().map(a=>a.id),...extra});
const startBalance=()=>visibleAccounts().filter(a=>state.account==='all'||a.id===state.account).reduce((s,a)=>s+a.balance,0);
const currentMetrics=()=>metrics(currentTrades(),startBalance());
const initials=name=>name.split(' ').map(x=>x[0]).slice(0,2).join('');
const activity=(text,type='update')=>{db.activity.unshift({id:uid(),text,time:new Date().toLocaleString('en-US',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}),type});persist();};
const userNav=[['WORKSPACE',[['overview','grid','Overview'],['trades','trades','Trade history'],['calendar','calendar','Trading calendar'],['analytics','chart','Analytics'],['journal','book','Daily journal']]],['MANAGEMENT',[['accounts','wallet','Accounts & licenses'],['reports','file','Reports'],['settings','settings','Settings']]]];
const adminNav=[['ADMIN WORKSPACE',[['overview','grid','Platform overview'],['users','users','Users'],['licenses','key','Licenses'],['accounts','wallet','Trading accounts'],['analytics','chart','Platform analytics'],['calendar','calendar','Trading calendar']]],['OPERATIONS',[['connections','pulse','Connections'],['activity','clock','Activity log'],['settings','settings','Platform settings']]]];
function parseRoute(){
 const route=location.hash.slice(1).split('/').filter(Boolean),previousContext=state.role+':'+state.viewUserId;
 if(['login','register','forgot','onboarding'].includes(route[0])){state.page=route[0];state.role='user';state.viewUserId=null;return;}
 state.role=route[0]==='admin'?'admin':'user';state.viewUserId=null;
 if(hasAdminAccess()&&route[1]==='users'&&route[2]){
  const user=db.users.find(u=>u.id===route[2]);
  if(user){state.viewUserId=user.id;state.page=route[3]||'overview';}
  else state.page='users';
 }else state.page=route[1]||'overview';
 if(previousContext!==state.role+':'+state.viewUserId)resetWorkspaceFilters();
 const valid=(isAdmin()?adminNav:userNav).flatMap(x=>x[1].map(x=>x[0])).concat(['help']);
 if(!valid.includes(state.page))state.page='overview';
 state.sidebar=false;state.query='';state.tradePage=1;
 if(!visibleAccounts().some(a=>a.id===state.account))state.account='all';
}
function navigate(page,role){location.hash=role?`/${role}/${page}`:workspaceHref(page).slice(1);}
function openUserWorkspace(id){
 if(!hasAdminAccess()||!db.users.some(u=>u.id===id))return;
 close();location.hash=`/admin/users/${encodeURIComponent(id)}/overview`;
}
function userWorkspaceBanner(){
 if(!state.viewUserId)return '';
 const user=activeUser();
 return `<section class="admin-view-banner" aria-label="Administrator viewing user workspace"><div class="admin-view-identity"><span class="admin-view-icon">${icon('shield')}</span><div><span class="eyebrow">ADMINISTRATOR · USER WORKSPACE</span><strong>Viewing ${esc(user.name)}’s panel</strong><small>${esc(user.email)} · ${esc(user.status)}</small></div></div><div class="admin-view-actions"><select id="view-user-switch" aria-label="View another user">${selectOptions(db.users.map(u=>[u.id,u.name]),user.id)}</select>${button('User details','user-profile:'+user.id,'secondary','users')}${button('Back to admin','back-to-admin','primary','arrow')}</div></section>`;
}
function toast(message){const el=document.querySelector('#toast-root');el.innerHTML=`<div class="toast">${icon('check')}<span>${esc(message)}</span></div>`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.innerHTML='',4000);}
function modal(title,body,footer='',wide=false){focusBeforeModal=document.activeElement;overlay.innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div><span class="eyebrow">STRUCTURE WORKSPACE</span><h2 id="modal-title">${title}</h2></div><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></header><div class="modal-content">${body}</div>${footer?`<footer>${footer}</footer>`:''}</section></div>`;document.body.classList.add('modal-open');setTimeout(()=>overlay.querySelector('input,select,textarea,button')?.focus(),0);}
function close(){overlay.innerHTML='';document.body.classList.remove('modal-open');focusBeforeModal?.focus?.();}
function pageHeading(kicker,title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div><div class="page-actions">${actions}</div></div>`;}
function panel(title,body,extra='',cls=''){return `<section class="panel ${cls}"><div class="panel-heading"><h3>${title}</h3>${extra}</div>${body}</section>`;}
function selectOptions(values,current){return values.map(([v,l])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join('');}
function filters(compact=false){return `<div class="filter-row"><div class="filter-group"><span class="filter-label">${icon('filter')} Filter by</span><select aria-label="Instrument" data-filter="symbol">${selectOptions([['all','All instruments'],...['XAUUSD','GBPUSD','EURUSD','BTCUSD'].map(x=>[x,x])],state.symbol)}</select><select aria-label="Trading session" data-filter="session">${selectOptions([['all','All sessions'],...['London','New York','Asia'].map(x=>[x,x])],state.session)}</select>${!compact?`<select aria-label="Trade result" data-filter="outcome">${selectOptions([['all','All results'],['win','Winning trades'],['loss','Losing trades']],state.outcome)}</select>`:''}</div>${button('Reset','reset-filters','text','refresh')}</div>`;}
function render(){document.documentElement.dataset.theme=db.theme||'light';if(['login','register','forgot','onboarding'].includes(state.page)){app.innerHTML=authPage();return;}
 const nav=isAdmin()?adminNav:userNav,person=isAdmin()?'Administrator':activeUser().name;
 app.innerHTML=`<div class="workspace ${state.collapsed?'is-collapsed':''} ${state.sidebar?'mobile-open':''}"><div class="mobile-scrim" data-action="sidebar"></div><aside class="sidebar"><a class="brand" href="${workspaceHref('overview')}" aria-label="Structure home"><img src="/assets/mark.svg" alt=""/><span>structure<span class="brand-dot">.</span><small>TRADING JOURNAL</small></span></a><div class="workspace-label">${icon(isAdmin()?'shield':'layers')}<span>${isAdmin()?'Admin workspace':state.viewUserId?'User workspace':'Personal workspace'}</span>${icon('down')}</div><nav aria-label="Main navigation">${nav.map(([label,items])=>`<div class="nav-group"><div class="nav-label">${label}</div>${items.map(([id,ic,label])=>`<a title="${label}" class="nav-link ${state.page===id?'active':''}" href="${workspaceHref(id)}">${icon(ic)}<span>${label}</span>${id==='journal'?'<em>'+userEntries().length+'</em>':id==='connections'&&isAdmin()?'<i class="notification-dot"></i>':''}</a>`).join('')}</div>`).join('')}</nav><div class="sidebar-bottom"><div class="insight-promo"><span class="promo-icon">${icon('spark')}</span><strong>Small habits. Real edge.</strong><p>Your next breakthrough starts with a review.</p><a href="${workspaceHref(isAdmin()?'analytics':'journal')}">${isAdmin()?'Explore performance':'Reflect on today'} ${icon('arrow')}</a></div><a href="${workspaceHref('help')}" class="nav-link ${state.page==='help'?'active':''}">${icon('help')}<span>Help & resources</span>${icon('external')}</a><button class="profile-switch" data-action="profile-menu">${avatar(person,isAdmin()?'purple':'gold',true)}<span><strong>${esc(person)}</strong><small>${isAdmin()?'Platform administrator':state.viewUserId?'Viewing as administrator':'Pro workspace'}</small></span>${icon('down')}</button></div><button class="collapse-btn" data-action="collapse" aria-label="Collapse navigation">${icon('chevron')}</button></aside><div class="main-shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn mobile-toggle" data-action="sidebar" aria-label="Open navigation">${icon('menu')}</button><span>${isAdmin()?'Administration':'Workspace'}</span>${icon('chevron')}<strong>${esc(nav.flatMap(x=>x[1]).find(x=>x[0]===state.page)?.[2]||'Help center')}</strong></div><div class="topbar-actions"><button class="search-shortcut" data-action="search">${icon('search')}<span>Quick search</span><kbd>⌘ K</kbd></button><span class="topbar-divider"></span><button class="demo-pill" data-action="demo-info"><i></i>Demo workspace</button><button class="icon-btn notification-btn" data-action="notifications" aria-label="Notifications">${icon('bell')}<i></i></button>${avatar(person,isAdmin()?'purple':'gold',true)}</div></header><main id="main" tabindex="-1">${userWorkspaceBanner()}<div class="workspace-toolbar"><div class="account-select">${icon(isAdmin()?'users':'wallet')}<select aria-label="Select trading account" id="account-filter">${selectOptions([['all',isAdmin()?'All trading accounts':'All accounts'],...visibleAccounts().map(a=>[a.id,a.name])],state.account)}</select><span class="count-pill">${visibleAccounts().length}</span></div><div class="toolbar-right"><span class="sync-status"><i></i>${isAdmin()?'Platform healthy':'Last synced 2 min ago'}</span><div class="date-select">${icon('calendar')}<select id="range-filter" aria-label="Date range">${selectOptions([['month','This month'],['week','This week'],['quarter','Last 3 months'],['all','All time']],state.range)}</select></div><button class="icon-btn" data-action="theme" aria-label="Toggle color theme">${icon('sun')}</button></div></div>${renderPage()}<footer class="page-footer"><span>Made for the trader you’re becoming.</span><span><i class="live-dot"></i> All systems operational <span class="footer-separator">·</span> Structure © 2026</span></footer></main></div></div>`;
}
function renderPage(){switch(state.page){case'overview':return isAdmin()?adminOverview():overview();case'trades':return tradesPage();case'calendar':return calendarPage();case'analytics':return analyticsPage();case'journal':return journalPage();case'accounts':case'licenses':return accountsPage();case'reports':return reportsPage();case'users':return usersPage();case'connections':return connectionsPage();case'activity':return activityPage();case'settings':return settingsPage();case'help':return helpPage();default:return overview();}}
function overview(){const m=currentMetrics(),trades=currentTrades(),daily=groupTrades(trades,'date').sort((a,b)=>a.name.localeCompare(b.name)),recent=[...trades].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)).slice(0,5),sessions=groupTrades(trades,'session');return `${pageHeading('YOUR PERFORMANCE, IN PERSPECTIVE','Every trade tells a story<span class="gold-text">.</span>','Your automated trading performance, synced into one clear workspace.',button('Export report','export','secondary','download'))}<div class="overview-meta"><span><i class="live-dot"></i> Performance overview</span><span>Oct 1 – Oct 16, 2026 <span class="muted">· USD</span></span></div><div class="metrics-grid">${metricCard('Net profit & loss',money(m.pnl,true),`<span class="positive-text">${icon('up')} ${(m.pnl/(startBalance()||1)*100).toFixed(2)}%</span><span>return this period</span>`,'wallet',sparkline(daily.map(x=>x.pnl)),'featured')}${metricCard('Win rate',m.winRate.toFixed(1)+'<small>%</small>',`<span class="positive-text">${m.wins} wins</span><span> / ${m.losses} losses</span>`,'target',`<div class="mini-progress"><i style="width:${m.winRate}%"></i></div>`)}${metricCard('Profit factor',Number.isFinite(m.pf)?m.pf.toFixed(2):'∞',`<span class="positive-text">${icon('check')} ${m.pf>=1?'Positive expectancy':'Review performance'}</span>`,'chart',sparkline(daily.map((x,i)=>1.5+(i%3)*.1+x.pnl/2000)))}${metricCard('Total trades',m.total,`<span>${m.avgR.toFixed(2)}R</span><span> average return / trade</span>`,'trades',`<div class="mini-blocks">${daily.slice(-14).map(x=>`<i class="${x.pnl>0?'win':'loss'}" style="height:${10+Math.min(Math.abs(x.pnl)/30,24)}px"></i>`).join('')}</div>`)}</div><div class="dashboard-primary">${panel('Account equity',`<div class="equity-summary"><div><span class="muted">${state.chartMode==='drawdown'?'Maximum drawdown':'Current equity'}</span><strong>${state.chartMode==='drawdown'?m.dd.toFixed(2)+'%':money(m.balance)}</strong></div><div class="chart-legend"><i></i>${state.chartMode==='drawdown'?'Drawdown':'Account balance'}</div></div>${state.chartMode==='drawdown'?drawdownChart(m):lineChart(m.curve)}<div class="equity-footer"><span>Starting balance <strong>${money(startBalance())}</strong></span><span>Max drawdown <strong>${m.dd.toFixed(2)}%</strong></span><span>Trading fees <strong>${money(m.fees)}</strong></span></div>`,`<div class="segmented"><button class="${state.chartMode==='equity'?'active':''}" data-action="chart-equity">Equity</button><button class="${state.chartMode==='drawdown'?'active':''}" data-action="chart-drawdown">Drawdown</button></div>`,'equity-panel')}${panel('Your trading edge',`<div class="edge-score"><div class="score-ring" style="--progress:${Math.round(m.winRate)}"><span>${Math.round(m.winRate)}<small>CONSISTENCY</small></span></div><div><span class="badge positive">Building momentum</span><p>Process first.<br>Performance follows.</p></div></div><div class="edge-stats"><div><span>Average win</span><strong>${money(m.avgWin)}</strong></div><div><span>Average loss</span><strong>${money(m.avgLoss)}</strong></div><div><span>Risk / reward</span><strong>1 : ${m.avgLoss?(m.avgWin/m.avgLoss).toFixed(2):'0.00'}</strong></div></div><a class="text-link" href="${workspaceHref('analytics')}">Explore your analytics ${icon('arrow')}</a>`,'<span class="subtle-icon">'+icon('spark')+'</span>','edge-panel')}</div><div class="dashboard-secondary">${panel('Daily performance',barChart(daily.slice(-12).map(x=>({...x,name:new Date(x.name+'T12:00:00').getDate().toString()}))),`<span class="muted small-text">Net P&L · October</span>`)}${panel('Performance by session',horizontalBars(sessions),`<a class="text-link" href="${workspaceHref('analytics')}">View all ${icon('arrow')}</a>`)}${panel('A moment to reflect',`<div class="reflection"><div class="reflection-illustration">${icon('book')}<span class="orbit orbit-one"></span><span class="orbit orbit-two"></span><i>✧</i></div><h3>Your EA runs.<br>Your insights grow.</h3><p>What did your automated system reveal today?</p>${button('Write a daily review','new-entry','secondary','edit')}</div>`,'<span class="badge neutral">DAILY JOURNAL</span>','reflection-panel')}</div>${panel('Recent trades',tradeTable(recent),`<a class="text-link" href="${workspaceHref('trades')}">View all trades ${icon('arrow')}</a>`)}<div class="bottom-note">${icon('shield')} Your accounts. Your data. Your edge. <span>Read-only connection — your funds stay with your broker.</span></div>`;}
function drawdownChart(m){let peak=m.curve[0]?.value||1;return lineChart(m.curve.map(p=>{peak=Math.max(peak,p.value);return {...p,value:-(peak-p.value)/peak*100};}),{id:'drawdown'});}
function tradeTable(trades,admin=false){if(!trades.length)return empty('No EA trades in this view','Try another filter, or connect your MT5 account to sync EA history.',button('Reset filters','reset-filters','secondary','refresh'));return `<div class="table-scroll"><table><thead><tr><th>Instrument</th><th>Direction</th><th>Date & time</th><th>Expert Advisor</th>${admin?'<th>Account</th>':''}<th>Net P&L</th><th>Return</th><th></th></tr></thead><tbody>${trades.map(t=>`<tr class="clickable" data-action="trade:${t.id}" tabindex="0" aria-label="View ${esc(t.symbol)} trade ${t.ticket}"><td><div class="instrument"><span class="instrument-mark ${t.symbol==='XAUUSD'?'gold':t.symbol==='BTCUSD'?'orange':'blue'}">${t.symbol==='XAUUSD'?'Au':t.symbol==='BTCUSD'?'₿':t.symbol.slice(0,2)}</span><span><strong>${t.symbol}</strong><small>${t.lots.toFixed(2)} lots <span>· ${t.source}</span></small></span></div></td><td>${badge(t.side)}</td><td><span>${dateLabel(t.date).replace(', 2026','')}</span><small class="block muted">${t.time} · ${esc(t.session)}</small></td><td><span class="setup-tag">${esc(t.eaName)}</span></td>${admin?`<td>${esc(db.accounts.find(a=>a.id===t.accountId)?.name)}</td>`:''}<td class="number ${t.pnl-t.fees>=0?'positive-text':'negative-text'}">${money(t.pnl-t.fees,true)}</td><td><span class="r-value ${t.r>0?'positive-text':'negative-text'}">${t.r>0?'+':''}${t.r.toFixed(2)}R</span></td><td>${icon('chevron')}</td></tr>`).join('')}</tbody></table></div>`;}
function tradesPage(){const trades=[...currentTrades()].sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)),m=metrics(trades),size=12,pages=Math.max(1,Math.ceil(trades.length/size));state.tradePage=Math.min(state.tradePage,pages);return `${pageHeading('THE DETAILS MAKE THE DIFFERENCE','Your trade history','Your EA executions, synced automatically from connected MT5 accounts.',button('Export CSV','export','secondary','download'))}${filters()}<div class="inline-summary"><span><strong>${m.total}</strong> trades</span><span>Net P&L <strong class="${m.pnl>=0?'positive-text':'negative-text'}">${money(m.pnl,true)}</strong></span><span>Win rate <strong>${m.winRate.toFixed(1)}%</strong></span><div class="table-search">${icon('search')}<input id="trade-search" aria-label="Search trades" placeholder="Search instrument, EA, ticket…" value="${esc(state.query)}"></div></div>${panel('All trades',tradeTable(trades.slice((state.tradePage-1)*size,state.tradePage*size))+`<div class="pagination"><span>Showing ${trades.length?(state.tradePage-1)*size+1:0}–${Math.min(state.tradePage*size,trades.length)} of ${trades.length} trades</span><div><button class="btn secondary" data-action="prev-trades" ${state.tradePage===1?'disabled':''}>Previous</button><span>${state.tradePage} / ${pages}</span><button class="btn secondary" data-action="next-trades" ${state.tradePage>=pages?'disabled':''}>Next</button></div></div>`,badge('EA sync only','neutral'))}`;}
function calendarPage(){const all=currentTrades({range:'all'}),cells=calendarCells(state.calendarYear,state.calendarMonth),monthKey=`${state.calendarYear}-${String(state.calendarMonth+1).padStart(2,'0')}`,monthTrades=all.filter(t=>t.date.startsWith(monthKey)),m=metrics(monthTrades),groups=Object.fromEntries(groupTrades(all,'date').map(x=>[x.name,x])),monthName=new Date(state.calendarYear,state.calendarMonth,1).toLocaleDateString('en-US',{month:'long',year:'numeric'}),winDays=Object.values(groups).filter(x=>x.name.startsWith(monthKey)&&x.pnl>0).length,lossDays=Object.values(groups).filter(x=>x.name.startsWith(monthKey)&&x.pnl<0).length;return `${pageHeading('SEE THE BIGGER PICTURE','Trading calendar','Your progress, one trading day at a time.',(isAdmin()?button('Export trades','export','primary','download'):button('Daily review','new-entry','primary','edit')))}<div class="calendar-summary">${metricCard('Monthly net P&L',money(m.pnl,true),`${m.total} trades this month`,'wallet')}${metricCard('Profitable days',winDays,`<span class="positive-text">${icon('up')} Consistency over intensity</span>`,'calendar')}${metricCard('Losing days',lossDays,'Every loss holds a lesson','shield')}${metricCard('Best day',money(Math.max(0,...Object.values(groups).filter(x=>x.name.startsWith(monthKey)).map(x=>x.pnl)),true),'Your strongest performance','flag')}</div><section class="panel calendar-panel"><div class="panel-heading"><div class="flex gap"><h3>${monthName}</h3><span class="badge neutral">${m.total} trades</span></div><div class="flex gap"><span class="calendar-legend"><i class="positive-dot"></i>Profit <i class="negative-dot"></i>Loss</span><button class="btn secondary compact" data-action="calendar-today">This month</button><button class="icon-btn bordered" data-action="calendar-prev" aria-label="Previous month">${icon('chevron','rotate')}</button><button class="icon-btn bordered" data-action="calendar-next" aria-label="Next month">${icon('chevron')}</button></div></div><div class="calendar-weekdays">${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells.map(c=>{const g=groups[c.date];return `<button class="calendar-cell ${!c.current?'outside':''} ${g?(g.pnl>0?'profit-day':'loss-day'):''} ${c.date===DEMO_TODAY?'today':''}" data-action="day:${c.date}" aria-label="${dateLabel(c.date)}, ${g?money(g.pnl,true)+', '+g.total+' trades':'no trades'}"><span class="day-number">${c.day}${c.date===DEMO_TODAY?'<small>TODAY</small>':''}</span>${g?`<strong>${money(g.pnl,true)}</strong><span class="day-trades">${g.total} trades <i>·</i> ${g.winRate.toFixed(0)}% win</span><div class="day-dots">${g.trades.slice(0,8).map(t=>`<i class="${t.pnl-t.fees>0?'win':'loss'}"></i>`).join('')}</div>`:'<span class="no-trades">—</span>'}</button>`;}).join('')}</div><div class="calendar-bottom"><span>${icon('eye')} Select a day to review trades and write a reflection.</span><strong class="${m.pnl>=0?'positive-text':'negative-text'}">Monthly return ${money(m.pnl,true)}</strong></div></section>`;}
function analyticsPage(){const trades=currentTrades(),m=metrics(trades,startBalance()),tab=state.analyticsTab,groups=groupTrades(trades,tab==='Instruments'?'symbol':tab==='Expert Advisors'?'eaName':tab==='Weekdays'?t=>new Date(t.date+'T12:00:00').toLocaleDateString('en-US',{weekday:'long'}):'session');return `${pageHeading('UNDERSTAND YOUR EDGE',isAdmin()?'Platform analytics':'Beyond the P&L','Find the patterns that make you a more consistent trader.',button('Export analysis','export','secondary','download'))}${filters(true)}<div class="tabs">${['Overview','Sessions','Instruments','Expert Advisors','Weekdays','Risk analysis'].map(x=>`<button class="${x===tab?'active':''}" data-action="analytics:${x}">${x}</button>`).join('')}</div><div class="metrics-grid">${metricCard('Expectancy',money(m.total?m.pnl/m.total:0,true),'Average net result per trade','target')}${metricCard('Average return',m.avgR.toFixed(2)+'R','Realized reward / initial risk','chart')}${metricCard('Max drawdown',m.dd.toFixed(2)+'%','Peak to trough in selected period','shield')}${metricCard('Average hold',Math.round(trades.reduce((s,t)=>s+t.duration,0)/(trades.length||1))+'<small>min</small>','Time in the market','clock')}</div>${tab==='Risk analysis'?`<div class="two-col">${panel('Execution outcomes',horizontalBars(groupTrades(trades,t=>t.pnl-t.fees>0?'Winning trades':'Losing trades')))}${panel('Your risk guardrails',`<div class="guardrails"><div>${icon('shield')}<span>Risk per trade</span><strong>${userSettings().risk.perTrade}%</strong></div><div>${icon('flag')}<span>Daily loss limit</span><strong>${userSettings().risk.dailyLoss}%</strong></div><div>${icon('trades')}<span>Maximum trades / day</span><strong>${userSettings().risk.maxTrades}</strong></div><p class="info-note">Guardrails help guide your reviews. In this UI demo they do not control your EA or broker account.</p>${button('Edit risk plan','risk-settings','secondary','edit')}</div>`)}${panel('Automated execution review',`<div class="insight-content">${icon('heart')}<h3>Monitor the system. Review the results.</h3><p>Compare your EAs by net return, drawdown, holding time, and execution volume. Use daily reviews to record system observations.</p><a href="${workspaceHref('journal')}" class="text-link">Open daily journal ${icon('arrow')}</a></div>`)}</div>`:`<div class="two-col">${panel(tab==='Overview'?'Equity progression':`Net return by ${tab.toLowerCase()}`,tab==='Overview'?lineChart(m.curve):barChart(groups))}${panel(tab==='Overview'?'Your best trading sessions':`${tab} breakdown`,horizontalBars(groups))}</div>${panel('Performance breakdown',`<div class="table-scroll"><table><thead><tr><th>${tab==='Overview'?'Session':tab}</th><th>Trades</th><th>Win rate</th><th>Profit factor</th><th>Average R</th><th>Net P&L</th></tr></thead><tbody>${groups.map(g=>`<tr><td><strong>${esc(g.name)}</strong></td><td>${g.total}</td><td>${g.winRate.toFixed(1)}%</td><td>${Number.isFinite(g.pf)?g.pf.toFixed(2):'∞'}</td><td>${g.avgR.toFixed(2)}R</td><td class="number ${g.pnl>=0?'positive-text':'negative-text'}">${money(g.pnl,true)}</td></tr>`).join('')}</tbody></table></div>`)}<div class="insight-banner">${icon('spark')}<div><strong>Let the data shape your process.</strong><p>${groups.length?`${esc([...groups].sort((a,b)=>b.pnl-a.pnl)[0].name)} leads your selected period. Review the EA executions behind those results before changing your configuration.`:'Connect an MT5 account to reveal your EA performance patterns.'}</p></div></div>`}`;}
function journalPage(){const entries=userEntries().filter(e=>(e.title+' '+e.content).toLowerCase().includes(state.journalQuery.toLowerCase()));return `${pageHeading('THE PART THE CHART DOESN’T SHOW','Your daily journal','Build self-awareness. Protect your mindset. Sharpen your process.',button('New reflection','new-entry','primary','plus'))}<div class="journal-layout"><div><div class="journal-intro"><div>${icon('book')}<span>One honest review is worth more than ten new indicators.</span></div><div class="table-search">${icon('search')}<input id="journal-search" value="${esc(state.journalQuery)}" placeholder="Search your reflections" aria-label="Search journal"></div></div>${entries.length?entries.map(e=>`<article class="journal-entry"><div class="entry-date"><strong>${new Date(e.date+'T12:00:00').getDate()}</strong><small>${new Date(e.date+'T12:00:00').toLocaleDateString('en-US',{month:'short'}).toUpperCase()}</small></div><div class="entry-body"><div class="flex between"><span class="muted small-text">${dateLabel(e.date)} · Daily reflection</span><button class="icon-btn" data-action="edit-entry:${e.id}" aria-label="Edit reflection">${icon('edit')}</button></div><h2>${esc(e.title)}</h2><p>${esc(e.content).replace(/\n/g,'<br>')}</p><div class="flex gap">${badge(e.mood)}<span class="entry-rating">${'★'.repeat(e.rating)}<span>${'★'.repeat(5-e.rating)}</span></span><small class="muted">Process rating</small></div></div></article>`).join(''):empty('A fresh page','Write your first reflection to start building your trading story.',button('Write reflection','new-entry','primary','edit'))}</div><aside>${panel('Your review ritual',`<ol class="ritual"><li><span>01</span><div><strong>Before the session</strong><p>How do I feel? What is my plan?</p></div></li><li><span>02</span><div><strong>After each trade</strong><p>Did I follow the rules I set?</p></div></li><li><span>03</span><div><strong>At the end of the day</strong><p>What will I do better tomorrow?</p></div></li></ol>`)}<blockquote>“The goal of a successful trader is to make the best trades. Money is secondary.”<cite>— Alexander Elder</cite></blockquote></aside></div>`;}
function accountsPage(){const accounts=visibleAccounts();return `${pageHeading(isAdmin()?'LICENSE & ACCOUNT MANAGEMENT':'ONE LICENSE. ONE TRADING ACCOUNT.',state.page==='licenses'?'License management':isAdmin()?'Trading accounts':'Accounts & licenses',isAdmin()?'Manage ownership, license access, and MT5 connection health.':'Your trading world, connected. Keep every account in one workspace.',isAdmin()?button('Issue license','issue-license','primary','plus'):button('Activate license','activate-license','primary','key'))}<div class="account-totals"><span>${icon('wallet')} <strong>${accounts.length}</strong> total accounts</span><span><i class="live-dot"></i><strong>${accounts.filter(a=>a.connection==='Connected').length}</strong> connected</span><span>${icon('key')}<strong>${accounts.filter(a=>a.status==='Active').length}</strong> active licenses</span><span>${icon('shield')} Read-only MT5 sync</span></div><div class="account-grid">${accounts.map(a=>{const user=db.users.find(u=>u.id===a.userId),m=metrics(db.trades.filter(t=>t.accountId===a.id),a.balance);return `<article class="panel account-card"><div class="account-card-top"><span class="broker-mark">${a.broker==='Not connected'?icon('plus'):a.broker.slice(0,2)}</span><div>${badge(a.connection)} <span class="account-type">${a.type}</span></div></div><h2>${esc(a.name)}</h2><p>${esc(a.broker)} ${a.number?'· #'+esc(a.number):'· Ready to connect'}${isAdmin()?`<br><small>Owned by ${esc(user?.name||'Unknown user')}</small>`:''}</p><div class="account-balance"><span>Account equity</span><strong>${money(m.balance)}</strong><span class="${m.pnl>=0?'positive-text':'negative-text'}">${money(m.pnl,true)} <span class="muted">all time</span></span></div><div class="license-line"><span>${icon('key')}<code>${esc(a.license)}</code></span><button class="icon-btn" data-action="copy:${a.license}" aria-label="Copy license">${icon('copy')}</button></div><div class="account-detail-row"><span>License status</span>${badge(a.status)}</div><div class="account-detail-row"><span>Valid until</span><strong>${dateLabel(a.expiry)}</strong></div><div class="account-detail-row"><span>Last sync</span><strong>${a.lastSync?dateLabel(a.lastSync.slice(0,10)):'Awaiting connection'}</strong></div><div class="account-card-actions">${a.status==='Active'?button(a.connection==='Connected'?'Connection details':'Connect MT5','connect:'+a.id,a.connection==='Connected'?'secondary':'primary','link'):button('License details','account:'+a.id,'secondary','key')}<button class="icon-btn bordered" data-action="account:${a.id}" aria-label="Manage ${esc(a.name)}">${icon('settings')}</button></div></article>`;}).join('')}</div><div class="connection-guide"><div class="guide-title">${icon('link')}<h3>From your terminal to your journal.</h3><p>Four simple steps. One connected workspace.</p></div>${[['01','Activate a license','Each license creates one journal account.'],['02','Connect your MT5','Bind the license to one account number.'],['03','Install the connector','Add the Structure bridge EA to your terminal.'],['04','Review your edge','Trades and performance appear in your journal.']].map(([n,t,d])=>`<div class="guide-step"><span>${n}</span><strong>${t}</strong><p>${d}</p></div>`).join('')}</div><p class="prototype-note">${icon('help')} UI preview: connection steps are simulated. A live MT5 bridge and license verification service are planned in the architecture README.</p>`;}
function reportsPage(){const m=currentMetrics();return `${pageHeading('PROGRESS WORTH REVIEWING','Reports & exports','A clear view of your performance, ready to take with you.',button('Export trades','export','primary','download'))}<div class="report-feature"><div><span class="eyebrow">OCTOBER 2026 · MONTHLY REVIEW</span><h2>A month of decisions.<br>A clearer picture of your edge.</h2><p>Your performance summary across the selected accounts.</p><div class="flex gap">${button('Open monthly report','monthly-report','primary','file')}${button('Download CSV','export','secondary','download')}</div></div><div class="report-preview"><div class="report-preview-top"><img src="/assets/mark.svg" alt="Structure mark"/><span>PERFORMANCE REPORT</span></div><span class="muted">Net performance</span><strong class="positive-text">${money(m.pnl,true)}</strong>${sparkline(m.curve.map(x=>x.value),'gold',true)}<div><span>Win rate <b>${m.winRate.toFixed(1)}%</b></span><span>Trades <b>${m.total}</b></span></div></div></div><div class="three-col">${[['Trade ledger','Every fill, fee, and realized result.','trades','export'],['Performance summary','A focused overview of your key metrics.','chart','summary-export'],['Daily breakdown','Daily results for your own analysis.','calendar','daily-export']].map(([t,d,ic,a])=>panel(t,`<div class="report-option">${icon(ic)}<p>${d}</p>${button('Download CSV',a,'secondary','download')}</div>`,badge('CSV','neutral'))).join('')}</div>`;}
function adminOverview(){const trades=currentTrades(),m=currentMetrics(),users=db.users,accountIds=visibleAccounts().map(a=>a.id),rank=users.map(u=>({...u,...metrics(trades.filter(t=>db.accounts.find(a=>a.id===t.accountId)?.userId===u.id))})).sort((a,b)=>b.pnl-a.pnl);return `${pageHeading('YOUR PLATFORM AT A GLANCE','A clear view of everyone<span class="gold-text">.</span>','Manage your traders, monitor account health, and see the bigger picture.',button('Issue license','issue-license','secondary','key')+button('Add user','add-user','primary','plus'))}<div class="metrics-grid">${metricCard('Platform net P&L',money(m.pnl,true),`${m.total} trades across the platform`,'chart',sparkline(m.curve.map(x=>x.value)),'featured')}${metricCard('Total users',users.length,`${users.filter(x=>x.status==='Active').length} active · ${users.filter(x=>x.status==='Invited').length} invited`,'users')}${metricCard('Active licenses',db.accounts.filter(a=>a.status==='Active').length,`${db.accounts.length} licenses issued`,'key')}${metricCard('Connected accounts',db.accounts.filter(a=>a.connection==='Connected').length,`<span class="negative-text">${db.accounts.filter(a=>a.connection==='Disconnected').length} need attention</span>`,'link')}</div><div class="dashboard-primary">${panel('Platform equity',lineChart(m.curve),badge('All selected accounts','neutral'))}${panel('Connection health',`<div class="health-ring">${icon('pulse')}<strong>${db.accounts.filter(a=>a.connection==='Connected').length}<small>CONNECTED</small></strong></div><div class="edge-stats"><div><span>Connected</span><strong class="positive-text">${db.accounts.filter(a=>a.connection==='Connected').length}</strong></div><div><span>Offline</span><strong class="negative-text">${db.accounts.filter(a=>a.connection==='Disconnected').length}</strong></div><div><span>Pending activation</span><strong>${db.accounts.filter(a=>!a.number).length}</strong></div></div><a class="text-link" href="#/admin/connections">Monitor connections ${icon('arrow')}</a>`)}</div><div class="two-col">${panel('Trader performance',`<div class="leaderboard">${rank.map((u,i)=>`<button data-action="user:${u.id}"><span class="rank">${String(i+1).padStart(2,'0')}</span>${avatar(u.name,u.color,true)}<span class="leader-name"><strong>${esc(u.name)}</strong><small>${u.total} trades · ${u.winRate.toFixed(0)}% win rate</small></span><strong class="${u.pnl>=0?'positive-text':'negative-text'}">${money(u.pnl,true)}</strong>${icon('chevron')}</button>`).join('')}</div>`,`<a href="#/admin/users" class="text-link">All users ${icon('arrow')}</a>`)}${panel('Recent activity',activityList(db.activity.slice(0,5)),`<a href="#/admin/activity" class="text-link">View log ${icon('arrow')}</a>`)}</div>`;}
function usersPage(){const users=db.users.filter(u=>(u.name+' '+u.email+' '+u.status).toLowerCase().includes(state.adminQuery.toLowerCase()));return `${pageHeading('PEOPLE BEHIND THE PERFORMANCE','User management','Invite traders, review performance, and manage account access.',button('Add user','add-user','primary','plus'))}<div class="inline-summary"><span><strong>${db.users.length}</strong> users</span><span><i class="live-dot"></i> ${db.users.filter(x=>x.status==='Active').length} active</span><div class="table-search">${icon('search')}<input id="admin-search" value="${esc(state.adminQuery)}" placeholder="Search users…" aria-label="Search users"></div></div>${panel('All users',users.length?`<div class="table-scroll"><table><thead><tr><th>User</th><th>Status</th><th>Licenses</th><th>Net P&L</th><th>Win rate</th><th>Joined</th><th></th></tr></thead><tbody>${users.map(u=>{const accounts=db.accounts.filter(a=>a.userId===u.id),m=metrics(db.trades.filter(t=>accounts.some(a=>a.id===t.accountId)));return `<tr class="clickable" tabindex="0" data-action="user:${u.id}"><td><div class="instrument">${avatar(u.name,u.color,true)}<span><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></span></div></td><td>${badge(u.status)}</td><td>${accounts.length} licenses</td><td class="number ${m.pnl>=0?'positive-text':'negative-text'}">${money(m.pnl,true)}</td><td>${m.winRate.toFixed(1)}%</td><td>${dateLabel(u.joined)}</td><td>${icon('chevron')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('No matching users','Try another name, email, or status.'))}`;}
function connectionsPage(){return `${pageHeading('KEEP YOUR DATA FLOWING','Connection monitor','Track MT5 heartbeats, sync status, and accounts that need attention.',button('Refresh status','refresh-connections','secondary','refresh'))}<div class="status-banner">${icon('shield')}<div><strong>Journal sync service · Demo mode</strong><p>Connection health and sync events below are sample data. Live heartbeats require the MT5 bridge.</p></div>${badge('Preview','neutral')}</div>${panel('MT5 connections',`<div class="table-scroll"><table><thead><tr><th>Account</th><th>Owner</th><th>Server</th><th>Status</th><th>Last heartbeat</th><th></th></tr></thead><tbody>${db.accounts.map(a=>`<tr><td><strong>${esc(a.name)}</strong><small class="block muted">${a.number?'#'+a.number:'Unbound license'}</small></td><td>${esc(db.users.find(u=>u.id===a.userId)?.name)}</td><td>${esc(a.server||'—')}</td><td>${badge(a.connection)}</td><td>${a.lastSync?esc(a.lastSync.replace('T',' ')):'Awaiting setup'}</td><td>${button('Inspect','connect:'+a.id,'secondary compact','eye')}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Sync event stream',activityList(db.activity.filter(x=>x.type==='sync')),badge('Sample events','neutral'))}`;}
function activityList(items){return items.length?`<div class="activity-list">${items.map(e=>`<div><span class="activity-icon">${icon(e.type==='sync'?'refresh':e.type==='license'?'key':e.type==='user'?'users':'clock')}</span><span><strong>${esc(e.text)}</strong><small>${esc(e.time)}</small></span><i class="live-dot"></i></div>`).join('')}</div>`:empty('No events yet','Workspace changes will appear here.');}
function activityPage(){return `${pageHeading('A TRANSPARENT WORKSPACE','Activity log','License changes, user actions, and connection events.',button('Export log','activity-export','secondary','download'))}${panel('Workspace activity',activityList(db.activity),badge(db.activity.length+' events','neutral'))}`;}
function settingsPage(){const tab=state.settingsTab,admin=isAdmin();return `${pageHeading('MAKE IT YOUR WORKSPACE',admin?'Platform settings':'Settings','The details that keep your workspace running smoothly.')}<div class="tabs">${['Profile','Preferences','Risk management','Notifications','Security'].map(x=>`<button class="${x===tab?'active':''}" data-action="settings:${x}">${x}</button>`).join('')}</div><div class="settings-layout"><section class="panel settings-panel">${tab==='Profile'?`<form id="profile-form"><h3>Personal information</h3><p class="muted">Your identity across your trading workspace.</p><div class="profile-photo">${avatar(userSettings().profile.name)}<div><strong>${esc(userSettings().profile.name)}</strong><small>${admin?'Administrator':'Workspace owner'}</small></div></div><div class="form-grid"><label>Full name<input name="name" value="${esc(userSettings().profile.name)}" required maxlength="70"></label><label>Email address<input type="email" name="email" value="${esc(userSettings().profile.email)}" required></label><label>Timezone<select name="timezone">${selectOptions(['Asia/Karachi','Europe/London','America/New_York','UTC'].map(x=>[x,x]),userSettings().profile.timezone)}</select></label><label>Reporting currency<select name="currency"><option>USD</option></select></label></div><p class="info-note">Account P&L stays in USD in this preview. Broker timestamp normalization belongs to the sync service.</p><div class="form-footer"><button class="btn primary" type="submit">Save changes ${icon('check')}</button></div></form>`:tab==='Risk management'?`<form id="risk-form"><h3>Your risk plan</h3><p class="muted">Make your rules clear before the session starts.</p><label>Risk per trade (%)<input name="perTrade" type="number" min="0.1" max="100" step="0.1" value="${userSettings().risk.perTrade}" required></label><label>Daily loss limit (%)<input name="dailyLoss" type="number" min="0.1" max="100" step="0.1" value="${userSettings().risk.dailyLoss}" required></label><label>Maximum trades per day<input name="maxTrades" type="number" min="1" max="100" value="${userSettings().risk.maxTrades}" required></label><div class="info-note">These settings are journal reminders. They do not place trades or enforce broker-side limits.</div><div class="form-footer"><button class="btn primary" type="submit">Save risk plan ${icon('check')}</button></div></form>`:tab==='Notifications'?`<form id="preferences-form"><h3>Stay in the loop</h3><p class="muted">Choose the updates that are useful to you.</p>${[['email','Email notifications','General workspace announcements.'],['sync','Connection alerts','When an MT5 account needs attention.'],['weekly','Weekly review','A reminder to review your trading process.']].map(([k,t,d])=>`<label class="toggle-row"><span><strong>${t}</strong><small>${d}</small></span><input type="checkbox" name="${k}" ${userSettings().preferences[k]?'checked':''}><i class="toggle"></i></label>`).join('')}<p class="info-note">Preferences are saved locally. No emails are sent by this UI demo.</p><div class="form-footer"><button class="btn primary" type="submit">Save preferences</button></div></form>`:tab==='Security'?`<h3>Security & access</h3><p class="muted">Account protection is part of a production-ready platform.</p><div class="security-row">${icon('lock')}<div><strong>Password</strong><small>Preview the password reset experience.</small></div>${button('Reset password','password-reset','secondary')}</div><div class="security-row">${icon('shield')}<div><strong>Two-factor authentication</strong><small>Planned for production authentication.</small></div>${badge('Planned','neutral')}</div><div class="security-row">${icon('globe')}<div><strong>Current session</strong><small>Demo workspace · This browser</small></div>${badge('Active')}</div><div class="form-footer">${button('Sign out of demo','signout','secondary','logout')}</div>`:`<h3>Workspace preferences</h3><p class="muted">A comfortable space to review your trading.</p><div class="toggle-row"><span><strong>Color appearance</strong><small>Switch between light and dark.</small></span>${button(db.theme==='dark'?'Use light theme':'Use dark theme','theme','secondary','sun')}</div><div class="toggle-row"><span><strong>Restore sample workspace</strong><small>Remove local edits and restore all sample data.</small></span>${button('Reset demo','reset-demo','secondary','refresh')}</div><p class="info-note">All demo changes are stored in this browser. Export any notes or trades you want to keep before resetting.</p>`}</section><aside class="settings-aside">${icon('shield')}<h3>A workspace you can trust.</h3><p>Your demo data stays in your browser. The planned production architecture scopes every trade to its account and owner.</p><a class="text-link" href="${workspaceHref('help')}">Connection & security guide ${icon('arrow')}</a></aside></div>`;}
function helpPage(){return `${pageHeading('A LITTLE GUIDANCE GOES A LONG WAY','Help & resources','Everything you need to feel at home in Structure.')}<div class="three-col">${[['Connect MT5','Follow the license-to-account setup flow.','link','help-connect'],['Explore the demo','Understand the user and administrator workspaces.','grid','demo-info'],['Export your data','Download the selected trades as a CSV.','download','export']].map(([t,d,ic,a])=>panel(t,`<div class="report-option">${icon(ic)}<p>${d}</p>${button('Get started',a,'secondary','arrow')}</div>`)).join('')}</div>${panel('Frequently asked questions',`<div class="faq">${[['How do accounts and licenses work?','One license represents one journal account. A user can hold multiple licenses. Each license is bound to a single MT5 account number and broker server.'],['Can I add trades myself?','Trade history is populated only by EA executions synced from connected MT5 accounts. Notes can annotate an execution while prices, volume, fees, and profit remain read-only.'],['Does Structure place trades?','No. The planned connector reads trading history and account snapshots. Trading permissions and broker credentials are not required by this journal.'],['Can the administrator see every user?','The admin UI has platform-wide statistics, user profiles, all licenses, and connection monitoring. Production access must be enforced by a backend role check.'],['Is this connected to a real trading account?','This version is a complete interactive UI prototype using deterministic sample trades and browser-local storage. Authentication, invitation delivery, licensing, and MT5 syncing are simulated.'],['Will my changes remain after refreshing?','Yes, changes are stored in this browser using localStorage. Reset demo in Settings to restore sample data.']].map(([q,a])=>`<details><summary>${q}${icon('plus')}</summary><p>${a}</p></details>`).join('')}</div>`)}`;}
function authPage(){const page=state.page,register=page==='register',forgot=page==='forgot',onboard=page==='onboarding';return `<div class="auth-layout"><section class="auth-story"><a class="brand" href="#/user/overview"><img src="/assets/mark.svg" alt=""><span>structure<span class="brand-dot">.</span><small>TRADING JOURNAL</small></span></a><div class="auth-story-main"><span class="eyebrow">YOUR PROCESS. YOUR PROGRESS.</span><h1>Build the trader<br>you want to<br><em>become.</em></h1><p>One workspace for every account.<br>One journal for every lesson.</p><div class="auth-art">${sparkline([2,3,2.5,5,4,6,5,7,6,9,8,11,10,14,13,16],'gold',true)}<span>${icon('chart')} Your edge, made visible.</span></div></div><small>A little more clarity. A lot more intention.</small></section><section class="auth-form-area"><a class="auth-back" href="#/user/overview">Explore the demo ${icon('arrow')}</a><div class="auth-form"><div class="auth-mark">${icon(forgot?'lock':onboard?'link':'layers')}</div><span class="eyebrow">${forgot?'A FRESH START':onboard?'YOUR WORKSPACE IS READY':'WELCOME TO STRUCTURE'}</span><h2>${forgot?'Reset your password':onboard?'Make yourself at home':register?'Start your trading story.':'Welcome back.'}</h2><p>${forgot?'Enter your email to preview the reset flow.':onboard?'Connect an account, or explore with sample data.':register?'A clearer perspective on every trade.':'Your next insight is waiting for you.'}</p>${onboard?`<div class="onboarding-steps"><div>${icon('check')}<span>Workspace created</span>${badge('Complete')}</div><div>${icon('wallet')}<span>Activate a license</span>${button('Activate','activate-license','secondary compact')}</div><div>${icon('link')}<span>Connect your MT5 terminal</span>${badge('Next','neutral')}</div></div>${button('Explore my workspace','enter-user','primary full','arrow')}`:`<form id="auth-form" data-mode="${page}">${register?'<label>Full name<input name="name" placeholder="Your full name" autocomplete="name" required maxlength="70"></label>':''}<label>Email address<input type="email" name="email" placeholder="you@example.com" autocomplete="email" required></label>${!forgot?`<label>Password<div class="password-field"><input type="password" name="password" placeholder="${register?'At least 8 characters':'Enter your password'}" minlength="8" autocomplete="${register?'new-password':'current-password'}" required><button type="button" class="icon-btn" data-action="toggle-password" aria-label="Show password">${icon('eye')}</button></div></label>${!register?'<a class="forgot-link" href="#/forgot">Forgot password?</a>':'<label class="checkbox-label"><input type="checkbox" required> I understand this is an interactive UI preview.</label>'}`:''}<button class="btn primary full" type="submit">${forgot?'Preview reset request':register?'Create demo workspace':'Sign in to demo'} ${icon('arrow')}</button></form>${!forgot?`<div class="auth-divider"><span>or explore without signing in</span></div><div class="demo-role-buttons">${button('User demo','enter-user','secondary','layers')}${button('Admin demo','enter-admin','secondary','shield')}</div><p class="auth-alt">${register?'Already have an account? <a href="#/login">Sign in</a>':'New to Structure? <a href="#/register">Create a workspace</a>'}</p>`:'<p class="auth-alt"><a href="#/login">Back to sign in</a></p>'}`}<div class="auth-demo-note">${icon('shield')} UI prototype · No real credentials required or stored.</div></div><small class="auth-copyright">© 2026 Structure. Every trade is a lesson.</small></section></div>`;}
function showTrade(id){const t=db.trades.find(t=>t.id===id);if(!t||!canAccessAccount(t.accountId))return;const a=db.accounts.find(a=>a.id===t.accountId);modal(`${esc(t.symbol)} <span class="muted">#${t.ticket}</span>`,`<div class="trade-detail-top"><div>${badge(t.side)} ${badge(t.source,'neutral')}</div><strong class="${t.pnl-t.fees>=0?'positive-text':'negative-text'}">${money(t.pnl-t.fees,true)}<small>Net profit & loss</small></strong></div><div class="trade-price-art"><span>ENTRY <strong>${t.entry.toFixed(t.symbol.endsWith('USD')&&t.entry<10?5:2)}</strong></span><div>${icon('arrow')}<span>${t.r>0?'+':''}${t.r.toFixed(2)}R</span></div><span>EXIT <strong>${t.exit.toFixed(t.entry<10?5:2)}</strong></span></div><div class="detail-grid">${[['Expert Advisor',t.eaName],['Magic number',t.magic],['Account',a?.name],['Date',dateLabel(t.date)],['Time / session',`${t.time} · ${t.session}`],['Position size',t.lots+' lots'],['Holding time',t.duration+' minutes'],['Commission & fees',money(t.fees)]].map(([k,v])=>`<div><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div><form id="trade-review-form" data-id="${id}"><div class="info-note">${icon('shield')} Synced execution data is read-only. Your review notes do not change MT5 trade history.</div><label>Trade notes<textarea name="notes" rows="4" placeholder="Record an observation about this EA execution.">${esc(t.notes)}</textarea></label><label class="checkbox-label"><input type="checkbox" name="reviewed" ${t.reviewed?'checked':''}> Mark this trade as reviewed</label><div class="form-footer">${button('Close','close','secondary')}<button class="btn primary" type="submit">Save review ${icon('check')}</button></div></form>`,'',true);}
function showDay(date){const trades=currentTrades({range:'all'}).filter(t=>t.date===date),m=metrics(trades),entry=userEntries().find(e=>e.date===date);modal(dateLabel(date),`<div class="day-detail-summary"><div><small>Net result</small><strong class="${m.pnl>=0?'positive-text':'negative-text'}">${money(m.pnl,true)}</strong></div><div><small>Trades</small><strong>${m.total}</strong></div><div><small>Win rate</small><strong>${m.winRate.toFixed(0)}%</strong></div></div>${tradeTable(trades)}<div class="day-reflection"><h3>Daily reflection</h3><p>${entry?esc(entry.content).replace(/\n/g,'<br>'):'A blank page is an opportunity. What did you learn today?'}</p>${isAdmin()?'':button(entry?'Edit reflection':'Write reflection','entry-date:'+date,'secondary','edit')}</div>`,'',true);}
function showEntry(id,date=DEMO_TODAY){const entry=userEntries().find(e=>e.id===id);if(id&&!entry)return;modal(entry?'Edit your reflection':'A moment for reflection',`<form id="entry-form" data-id="${entry?.id||''}"><label>Date<input type="date" name="date" value="${entry?.date||date}" required></label><label>Give today a title<input name="title" value="${esc(entry?.title||'')}" placeholder="What’s your biggest takeaway?" required maxlength="120"></label><div class="form-grid"><label>How did you feel?<select name="mood">${selectOptions(['Focused','Calm','Confident','Impatient','Anxious'].map(x=>[x,x]),entry?.mood||'Focused')}</select></label><label>Process rating<select name="rating">${selectOptions([1,2,3,4,5].map(x=>[String(x),`${x} / 5 ${'★'.repeat(x)}`]),String(entry?.rating||4))}</select></label></div><label>Your reflection<textarea name="content" rows="7" placeholder="Did you follow your plan? What worked? What will you improve tomorrow?" required>${esc(entry?.content||'')}</textarea></label><div class="form-footer">${entry?button('Delete','delete-entry:'+entry.id,'danger text','trash'):button('Cancel','close','secondary')}<button type="submit" class="btn primary">Save reflection ${icon('check')}</button></div></form>`);}
function showUser(id){if(!hasAdminAccess())return;const u=db.users.find(u=>u.id===id);if(!u)return;const accounts=db.accounts.filter(a=>a.userId===id),trades=db.trades.filter(t=>accounts.some(a=>a.id===t.accountId)),m=metrics(trades);modal('Trader profile',`<div class="user-profile-heading">${avatar(u.name,u.color)}<div><h2>${esc(u.name)}</h2><p>${esc(u.email)}</p>${badge(u.status)}</div></div><div class="day-detail-summary"><div><small>Net P&L · All time</small><strong class="${m.pnl>=0?'positive-text':'negative-text'}">${money(m.pnl,true)}</strong></div><div><small>Win rate</small><strong>${m.winRate.toFixed(1)}%</strong></div><div><small>Trades</small><strong>${m.total}</strong></div></div>${lineChart(m.curve)}<h3>Accounts & licenses</h3>${accounts.length?accounts.map(a=>`<button class="account-list-item" data-action="account:${a.id}">${icon('wallet')}<span><strong>${esc(a.name)}</strong><small>${esc(a.license)}</small></span>${badge(a.status)}${icon('chevron')}</button>`).join(''):empty('No licenses yet','Issue a license to give this user their first trading account.')}<div class="form-footer">${button(u.status==='Suspended'?'Restore access':'Suspend user','toggle-user:'+id,u.status==='Suspended'?'secondary':'danger text','shield')}${button('Open full panel','open-panel:'+id,'secondary','external')}${button('Issue license','issue-for:'+id,'primary','key')}</div>`,'',true);}
function showAddUser(){if(!isAdmin())return;modal('Add a trader',`<p class="muted">Create a user profile and optionally issue their first account license.</p><form id="user-form"><label>Full name<input name="name" placeholder="e.g. Sarah Chen" required maxlength="70"></label><label>Email address<input name="email" type="email" placeholder="trader@example.com" required></label><label>Initial access<select name="status"><option>Active</option><option>Invited</option></select></label><label class="checkbox-label"><input type="checkbox" name="license" checked> Issue a license for their first trading account</label><p class="info-note">Demo action: this creates a local user record. No invitation email is sent.</p><div class="form-footer">${button('Cancel','close','secondary')}<button class="btn primary" type="submit">Create user ${icon('plus')}</button></div></form>`);}
function showIssue(userId=''){if(!hasAdminAccess())return;modal('Issue an account license',`<form id="license-form"><label>Assign to user<select name="userId" required>${selectOptions(db.users.filter(u=>u.status!=='Suspended').map(u=>[u.id,`${u.name} · ${u.email}`]),userId)}</select></label><label>Account name<input name="name" placeholder="e.g. Funded account" required maxlength="65"></label><div class="form-grid"><label>Account type<select name="type"><option>Live</option><option>Funded</option><option>Demo</option></select></label><label>License expiry<input type="date" name="expiry" value="2027-10-18" min="2026-10-18" required></label></div><label>Starting balance (USD)<input name="balance" type="number" min="0" value="10000" required></label><div class="info-note">One license creates one journal account. The owner will bind their MT5 account when connecting.</div><div class="form-footer">${button('Cancel','close','secondary')}<button class="btn primary" type="submit">Generate license ${icon('key')}</button></div></form>`);}
function newAccount({userId,name,type='Live',balance=0,expiry='2027-10-18',license}){return {id:uid(),userId,name,type,balance:Number(balance),expiry,license:license||'STRC-'+uid().replaceAll('-','').slice(0,4).toUpperCase()+'-'+uid().replaceAll('-','').slice(0,4).toUpperCase(),status:'Active',connection:'Not connected',number:'',broker:'Not connected',server:'',currency:'USD',lastSync:null,created:DEMO_TODAY};}
function showActivate(){modal('Activate a license',`<form id="activate-form"><p class="muted">A license gives one MT5 account its own home in your journal.</p><label>License key<input name="license" placeholder="STRC-XXXX-XXXX" pattern="STRC-[A-Za-z0-9]{4}-[A-Za-z0-9]{4}" required><small class="muted">Try STRC-DEMO-2026 to preview activation.</small></label><label>Account nickname<input name="name" placeholder="e.g. My funded account" required maxlength="65"></label><label>Account type<select name="type"><option>Live</option><option>Funded</option><option>Demo</option></select></label><p class="info-note">Demo activation accepts the sample key above. Production keys must be verified by the license service.</p><div class="form-footer">${button('Cancel','close','secondary')}<button class="btn primary" type="submit">Activate account ${icon('arrow')}</button></div></form>`);}
function showAccount(id){const a=db.accounts.find(a=>a.id===id);if(!a||(!isAdmin()&&a.userId!==activeUserId()))return;modal('Account settings',`<form id="account-form" data-id="${id}"><label>Account name<input name="name" value="${esc(a.name)}" required maxlength="65"></label><div class="license-display"><span class="eyebrow">ACCOUNT LICENSE</span><code>${esc(a.license)}</code>${badge(a.status)}</div><div class="detail-grid"><div><small>MT5 account</small><strong>${esc(a.number||'Not bound')}</strong></div><div><small>Server</small><strong>${esc(a.server||'Not connected')}</strong></div><div><small>Owner</small><strong>${esc(db.users.find(u=>u.id===a.userId)?.name)}</strong></div><div><small>Expiry</small><strong>${dateLabel(a.expiry)}</strong></div></div>${hasAdminAccess()?`<label>License status<select name="status">${selectOptions(['Active','Suspended','Revoked'].map(x=>[x,x]),a.status)}</select></label><label>Expiry date<input type="date" name="expiry" value="${a.expiry}" required></label>`:''}<div class="form-footer">${a.connection==='Connected'?button('Disconnect','disconnect:'+a.id,'danger text','link'):button('Close','close','secondary')}<button type="submit" class="btn primary">Save changes ${icon('check')}</button></div></form>`);}
let wizard={};
function showConnect(id,step=1,preserve=false){const a=db.accounts.find(a=>a.id===id);if(!a||(!isAdmin()&&a.userId!==activeUserId()))return;if(a.status!=='Active'){modal('License needs attention',`<p>This license is ${esc(a.status.toLowerCase())}. An administrator must restore it before connecting an MT5 account.</p>`,button('Close','close','secondary'));return;}
 if(step===1&&!preserve)wizard={id,number:a.number,broker:a.broker==='Not connected'?'':a.broker,server:a.server};
 modal(step===4?'Your account is ready.':'Connect your MT5 account',`<div class="wizard-steps">${['Account','Connector','Verify'].map((s,i)=>`<span class="${step>i+1?'done':step===i+1?'current':''}"><i>${step>i+1?icon('check'):i+1}</i>${s}</span>`).join('')}</div>${step===1?`<form id="connect-form" data-id="${id}"><div class="info-note">${icon('shield')} Read-only connection. Never share your trading or investor password here.</div><label>Journal account<input value="${esc(a.name)}" disabled></label><label>MT5 account number<input name="number" inputmode="numeric" pattern="[0-9]{4,15}" value="${esc(wizard.number)}" placeholder="e.g. 20891476" required ${a.number?'readonly':''}></label><div class="form-grid"><label>Broker<input name="broker" value="${esc(wizard.broker)}" placeholder="e.g. Exness" required maxlength="50" ${a.number?'readonly':''}></label><label>MT5 server<input name="server" value="${esc(wizard.server)}" placeholder="Exness-MT5Real" required maxlength="70" ${a.number?'readonly':''}></label></div>${a.number?'<small class="muted">The license is bound to this account. Contact an administrator to rebind it.</small>':''}<div class="form-footer">${button('Cancel','close','secondary')}<button type="submit" class="btn primary">Continue ${icon('arrow')}</button></div></form>`:step===2?`<h3>Set up your terminal connector</h3><p class="muted">In the production flow, add the Structure bridge EA to an MT5 chart and enter these values.</p><div class="connector-values"><div><span>License key</span><code>${esc(a.license)}</code><button class="icon-btn" data-action="copy:${a.license}" aria-label="Copy license">${icon('copy')}</button></div><div><span>MT5 account</span><strong>${esc(wizard.number)}</strong></div><div><span>Broker server</span><strong>${esc(wizard.server)}</strong></div></div><ol class="number-list"><li>Place the bridge EA in your terminal’s Experts folder.</li><li>Allow WebRequest to your deployed journal API.</li><li>Attach the connector to one chart and enter the license.</li><li>Keep the terminal or VPS running to sync new trades.</li></ol><div class="info-note">The bridge EA is a future backend deliverable. This preview does not download or install an EA.</div><div class="form-footer">${button('Back','connect-back:'+id,'secondary')}${button('Continue to verification','connect-verify:'+id,'primary','arrow')}</div>`:step===3?`<div class="verify-visual">${icon('pulse')}<h3>Ready to test your connection</h3><p>Account #${esc(wizard.number)} · ${esc(wizard.broker)}</p></div><div class="verification-lines"><span>${icon('check')} Account details captured</span><span>${icon('check')} License-to-account mapping ready</span><span>${icon('clock')} Awaiting connector handshake</span></div><div class="info-note">This is a simulation. No broker connection or data transfer will occur.</div><div class="form-footer">${button('Back','connect-install:'+id,'secondary')}${button('Simulate successful connection','connect-finish:'+id,'primary','check')}</div>`:`<div class="success-visual">${icon('check')}<h3>One more account. One clear view.</h3><p>${esc(a.name)} is marked connected in this demo. Real trade syncing requires the live MT5 bridge.</p></div><div class="form-footer">${button('Back to accounts','connection-done','primary','arrow')}</div>`}`,'',false);
}
function downloadCSV(name,rows){const csv=rows.map(r=>r.map(x=>{let v=String(x??'');if(/^[=+@\t\r]/.test(v)||/^-(?!\d)/.test(v))v="'"+v;return '"'+v.replaceAll('"','""')+'"';}).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');a.href=url;a.download=name+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your CSV export is ready.');}
function exportTrades(){downloadCSV('structure-trades', [['Ticket','Account','Date','Time','Instrument','Direction','Entry','Exit','Lots','Gross P&L','Fees','Net P&L','R','Session','Expert Advisor','Magic number','Notes'],...currentTrades().map(t=>[t.ticket,db.accounts.find(a=>a.id===t.accountId)?.name,t.date,t.time,t.symbol,t.side,t.entry,t.exit,t.lots,t.pnl,t.fees,(t.pnl-t.fees).toFixed(2),t.r,t.session,t.eaName,t.magic,t.notes])]);}
function monthlyReport(){const m=currentMetrics();modal('Your performance report',`<div class="report-modal-brand"><img src="/assets/mark.svg" alt="Structure"><span>STRUCTURE / MONTHLY REVIEW</span></div><h3>October 2026</h3><p class="muted">${state.account==='all'?'All selected accounts':esc(db.accounts.find(a=>a.id===state.account)?.name)} · ${state.range} date filter</p><div class="day-detail-summary"><div><small>Net P&L</small><strong class="positive-text">${money(m.pnl,true)}</strong></div><div><small>Win rate</small><strong>${m.winRate.toFixed(1)}%</strong></div><div><small>Trades</small><strong>${m.total}</strong></div></div>${lineChart(m.curve)}<div class="detail-grid"><div><small>Profit factor</small><strong>${Number.isFinite(m.pf)?m.pf.toFixed(2):'∞'}</strong></div><div><small>Average return</small><strong>${m.avgR.toFixed(2)}R</strong></div><div><small>Maximum drawdown</small><strong>${m.dd.toFixed(2)}%</strong></div><div><small>Total fees</small><strong>${money(m.fees)}</strong></div></div>`,button('Download metrics CSV','summary-export','primary','download'),true);}
function confirmation(title,text,action,label='Confirm'){modal(title,`<p>${text}</p>`,button('Cancel','close','secondary')+button(label,action,'danger','check'));}
async function handleAction(action,el){const [type,...rest]=action.split(':'),id=rest.join(':');switch(type){
case'close':close();break;
case'sidebar':state.sidebar=!state.sidebar;render();break;
case'collapse':state.collapsed=!state.collapsed;render();break;
case'theme':db.theme=db.theme==='dark'?'light':'dark';persist();render();break;
case'chart-equity':case'chart-drawdown':state.chartMode=type==='chart-equity'?'equity':'drawdown';render();break;
case'profile-menu':modal('Your workspace',`<div class="profile-photo">${avatar(userSettings().profile.name)}<div><strong>${esc(userSettings().profile.name)}</strong><small>${esc(userSettings().profile.email)}</small></div></div><div class="workspace-options">${button('User workspace','enter-user','secondary full','layers')}${button('Admin workspace','enter-admin','secondary full','shield')}${button('Preview sign-in flow','signout','secondary full','logout')}</div><p class="info-note">Role switching is for exploring this prototype. Production roles are assigned and verified by the backend.</p>`);break;
case'enter-user':case'enter-admin':close();state.account='all';navigate('overview',type==='enter-user'?'user':'admin');if(location.hash===`/${type==='enter-user'?'user':'admin'}/overview`){parseRoute();render();}break;
case'signout':close();location.hash='/login';break;
case'demo-info':modal('A complete workspace preview',`<div class="info-note">You’re exploring a frontend prototype with sample trading data from August–October 2026.</div><ul class="demo-features"><li>${icon('check')} Review, filter, and export trade history</li><li>${icon('check')} Explore the calendar and account analytics</li><li>${icon('check')} Save daily reviews and EA execution notes</li><li>${icon('check')} Manage users and licenses as an administrator</li></ul><p>Changes persist in this browser. Authentication, email delivery, license validation, and MT5 sync are simulated.</p>`,button('User workspace','enter-user','secondary')+button('Explore admin','enter-admin','primary','shield'));break;
case'notifications':modal('You’re up to date',`<div class="activity-list"><div><span class="activity-icon">${icon('refresh')}</span><span><strong>Your trading history is up to date</strong><small>Sample sync · October 16, 15:42</small></span></div><div><span class="activity-icon">${icon('book')}</span><span><strong>A little reflection goes a long way</strong><small>Take a moment to write today’s review.</small></span></div><div><span class="activity-icon">${icon('key')}</span><span><strong>Strategy lab is ready to connect</strong><small>Activate your MT5 account connection.</small></span></div></div>`,button('Done','close','primary'));break;
case'search':modal('Where would you like to go?',`<div class="search-input-large">${icon('search')}<input id="command-search" autofocus placeholder="Search pages, accounts, tools…" aria-label="Search workspace"></div><div id="command-results">${commandResults('')}</div>`);break;
case'goto':close();navigate(id);break;
case'reset-filters':Object.assign(state,{symbol:'all',session:'all',outcome:'all',query:'',tradePage:1});render();break;
case'trade':showTrade(id);break;
case'day':showDay(id);break;
case'calendar-prev':case'calendar-next':{const d=new Date(state.calendarYear,state.calendarMonth+(type==='calendar-next'?1:-1),1);state.calendarYear=d.getFullYear();state.calendarMonth=d.getMonth();render();break;}
case'calendar-today':state.calendarYear=2026;state.calendarMonth=9;render();break;
case'prev-trades':state.tradePage=Math.max(1,state.tradePage-1);render();break;
case'next-trades':state.tradePage++;render();break;
case'analytics':state.analyticsTab=id;render();break;
case'settings':state.settingsTab=id;render();break;
case'risk-settings':state.settingsTab='Risk management';navigate('settings');break;
case'new-entry':showEntry();break;
case'edit-entry':showEntry(id);break;
case'entry-date':showEntry(userEntries().find(e=>e.date===id)?.id,id);break;
case'delete-entry':confirmation('Delete this reflection?','This removes this reflection from your local journal.','confirm-delete-entry:'+id,'Delete reflection');break;
case'confirm-delete-entry':db.entries=db.entries.filter(e=>e.id!==id||e.userId!==activeUserId());persist();close();render();toast('Reflection deleted.');break;
case'add-user':showAddUser();break;
case'user':openUserWorkspace(id);break;
case'user-profile':if(hasAdminAccess())showUser(id);break;
case'open-panel':openUserWorkspace(id);break;
case'back-to-admin':close();navigate('users','admin');break;
case'toggle-user':{if(!hasAdminAccess())return;const u=db.users.find(u=>u.id===id);confirmation(u.status==='Suspended'?'Restore user access?':'Suspend this user?',u.status==='Suspended'?'The user will return to active status. Licenses remain unchanged.':'This changes the demo user status and suspends their active account licenses.','confirm-toggle-user:'+id,u.status==='Suspended'?'Restore access':'Suspend user');break;}
case'confirm-toggle-user':{if(!hasAdminAccess())return;const u=db.users.find(u=>u.id===id),restore=u.status==='Suspended';u.status=restore?'Active':'Suspended';if(!restore)db.accounts.filter(a=>a.userId===id&&a.status==='Active').forEach(a=>{a.status='Suspended';a.connection='Disconnected';});activity(`${restore?'Restored':'Suspended'} user · ${u.name}`,'user');close();render();toast('User status updated.');break;}
case'issue-license':showIssue();break;
case'issue-for':showIssue(id);break;
case'activate-license':showActivate();break;
case'account':showAccount(id);break;
case'connect':showConnect(id);break;
case'connect-back':showConnect(id,1,true);break;
case'connect-install':showConnect(id,2);break;
case'connect-verify':showConnect(id,3);break;
case'connect-finish':{const a=db.accounts.find(a=>a.id===id);if(!a||a.status!=='Active'||!canAccessAccount(a.id)||wizard.id!==id)return;a.number=wizard.number;a.broker=wizard.broker;a.server=wizard.server;a.connection='Connected';a.lastSync=new Date().toISOString().slice(0,19);activity('Demo connection verified · '+a.name,'sync');render();showConnect(id,4);break;}
case'connection-done':close();navigate('accounts');render();break;
case'disconnect':confirmation('Disconnect this account?','Trade history is retained. The account can be reconnected later.','confirm-disconnect:'+id,'Disconnect');break;
case'confirm-disconnect':{const a=db.accounts.find(a=>a.id===id);if(!a||(!isAdmin()&&a.userId!==activeUserId()))return;a.connection='Disconnected';activity('Account disconnected · '+a.name,'sync');close();render();toast('Account disconnected.');break;}
case'copy':try{await navigator.clipboard.writeText(id);toast('Copied to clipboard.');}catch{modal('Copy this value',`<input value="${esc(id)}" readonly onclick="this.select()" aria-label="Value to copy">`,button('Done','close','primary'));}break;
case'export':exportTrades();break;
case'summary-export':{const m=currentMetrics();downloadCSV('structure-performance',[['Metric','Value'],['Net P&L',m.pnl.toFixed(2)],['Trades',m.total],['Win rate',m.winRate.toFixed(2)],['Profit factor',Number.isFinite(m.pf)?m.pf.toFixed(2):'Infinity'],['Average R',m.avgR.toFixed(2)],['Max drawdown %',m.dd.toFixed(2)],['Fees',m.fees.toFixed(2)]]);break;}
case'daily-export':downloadCSV('structure-daily',[['Date','Trades','Net P&L','Win rate'],...groupTrades(currentTrades(),'date').map(g=>[g.name,g.total,g.pnl.toFixed(2),g.winRate.toFixed(2)])]);break;
case'activity-export':if(isAdmin())downloadCSV('structure-activity',[['Time','Event','Type'],...db.activity.map(e=>[e.time,e.text,e.type])]);break;
case'monthly-report':monthlyReport();break;
case'password-reset':close();location.hash='/forgot';break;
case'toggle-password':{const input=el.closest('.password-field').querySelector('input');input.type=input.type==='password'?'text':'password';el.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');break;}
case'help-connect':showConnect(visibleAccounts().find(a=>a.status==='Active')?.id);break;
case'refresh-connections':toast('Sample connection statuses refreshed. Live polling requires the MT5 bridge.');break;
case'reset-demo':confirmation('Restore the sample workspace?','This deletes local edits to trades, journals, users, licenses, and settings.','confirm-reset-demo','Restore sample data');break;
case'confirm-reset-demo':localStorage.removeItem('structure-v1');db=loadState();close();state.account='all';if(state.viewUserId&&!db.users.some(u=>u.id===state.viewUserId)){state.viewUserId=null;navigate('users','admin');parseRoute();}render();toast('Sample workspace restored.');break;
}}
function commandResults(q){const nav=isAdmin()?adminNav:userNav;const items=nav.flatMap(x=>x[1]).filter(x=>x[2].toLowerCase().includes(q.toLowerCase()));return items.length?`<div class="command-list">${items.map(([id,ic,label])=>`<button data-action="goto:${id}">${icon(ic)}<span>${label}</span>${icon('arrow')}</button>`).join('')}</div>`:empty('No matching pages','Try “calendar”, “accounts”, or “analytics”.');}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled)handleAction(el.dataset.action,el);else if(e.target.classList.contains('modal-backdrop'))close();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();state.sidebar=false;document.querySelector('.workspace')?.classList.remove('mobile-open');}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();handleAction('search');}if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-action]')){e.preventDefault();handleAction(e.target.dataset.action,e.target);}if(e.key==='Tab'&&overlay.firstChild){const els=[...overlay.querySelectorAll('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]')];const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('change',e=>{if(e.target.id==='view-user-switch'){if(hasAdminAccess())location.hash=`/admin/users/${encodeURIComponent(e.target.value)}/${state.page}`;}else if(e.target.id==='account-filter'){state.account=e.target.value;state.tradePage=1;render();}else if(e.target.id==='range-filter'){state.range=e.target.value;state.tradePage=1;render();}else if(e.target.dataset.filter){state[e.target.dataset.filter]=e.target.value;state.tradePage=1;render();}});
let searchTimeout;document.addEventListener('input',e=>{if(e.target.id==='command-search'){document.querySelector('#command-results').innerHTML=commandResults(e.target.value);return;}const map={'trade-search':'query','journal-search':'journalQuery','admin-search':'adminQuery'},key=map[e.target.id];if(key){const id=e.target.id,value=e.target.value,start=e.target.selectionStart;state[key]=value;state.tradePage=1;clearTimeout(searchTimeout);searchTimeout=setTimeout(()=>{render();const input=document.getElementById(id);input?.focus();input?.setSelectionRange(start,start);},180);}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(!form.checkValidity()){form.reportValidity();return;}const f=Object.fromEntries(new FormData(form)),id=form.dataset.id;
 switch(form.id){case'profile-form':userSettings().profile={...userSettings().profile,...f,name:f.name.trim()};Object.assign(db.users.find(u=>u.id===activeUserId()),{name:userSettings().profile.name,email:userSettings().profile.email});activity('Profile updated');break;
 case'risk-form':userSettings().risk={perTrade:Number(f.perTrade),dailyLoss:Number(f.dailyLoss),maxTrades:Number(f.maxTrades)};activity('Risk plan updated');break;
 case'preferences-form':userSettings().preferences={email:!!f.email,sync:!!f.sync,weekly:!!f.weekly};break;
 case'trade-review-form':{const t=db.trades.find(t=>t.id===id);if(!t||(!isAdmin()&&db.accounts.find(a=>a.id===t.accountId)?.userId!==activeUserId()))return;Object.assign(t,{notes:f.notes,reviewed:!!f.reviewed});break;}
 case'entry-form':{if(!f.title.trim()||!f.content.trim())return;if(id&&!userEntries().some(e=>e.id===id))return;const entry={...f,id:id||uid(),userId:activeUserId(),rating:Number(f.rating),title:f.title.trim()};if(id)db.entries=db.entries.map(x=>x.id===id?entry:x);else db.entries.unshift(entry);db.entries.sort((a,b)=>b.date.localeCompare(a.date));break;}
 case'user-form':{if(!isAdmin())return;if(db.users.some(u=>u.email.toLowerCase()===f.email.toLowerCase())){toast('A user with this email already exists.');return;}if(!f.name.trim())return;const u={id:uid(),name:f.name.trim(),email:f.email,initials:initials(f.name),status:f.status,joined:DEMO_TODAY,color:'purple'};db.users.push(u);if(f.license)db.accounts.push(newAccount({userId:u.id,name:u.name.split(' ')[0]+' · Trading account',balance:10000}));activity('User created · '+u.name,'user');break;}
 case'license-form':{if(!hasAdminAccess())return;db.accounts.push(newAccount(f));activity('License issued · '+f.name,'license');break;}
 case'activate-form':{const key=f.license.toUpperCase();if(db.accounts.some(a=>a.license===key)){toast('This license is already activated or assigned.');return;}if(key!=='STRC-DEMO-2026'){toast('Use the sample key STRC-DEMO-2026 in this preview.');return;}const a=newAccount({userId:activeUserId(),name:f.name,type:f.type,license:key});db.accounts.push(a);activity('Demo license activated · '+a.name,'license');close();if(state.page==='onboarding')navigate('accounts','user');render();showConnect(a.id);return;}
 case'account-form':{const a=db.accounts.find(a=>a.id===id);if(!a||(!isAdmin()&&a.userId!==activeUserId()))return;a.name=f.name.trim();if(hasAdminAccess()){a.status=f.status;a.expiry=f.expiry;if(a.status!=='Active')a.connection='Disconnected';activity('License updated · '+a.name,'license');}break;}
 case'connect-form':{const a=db.accounts.find(a=>a.id===id);if(!a||!canAccessAccount(a.id))return;const owner=db.users.find(u=>u.id===a.userId);if(owner?.status==='Suspended'){toast('Restore this user before connecting an account.');return;}if(db.accounts.some(a=>a.id!==id&&a.number===f.number&&a.server.toLowerCase()===f.server.toLowerCase())){toast('This MT5 account and server are already bound to another license.');return;}wizard={id,...f};showConnect(id,2);return;}
 case'auth-form':{if(form.dataset.mode==='forgot'){modal('Reset flow preview',`<div class="success-visual">${icon('mail')}<h3>Request captured.</h3><p>In production, a password reset link would be sent to ${esc(f.email)} if an account exists. This demo does not send email.</p></div>`,button('Back to sign in','signout','primary','arrow'));return;}if(form.dataset.mode==='register'){userSettings().profile.name=f.name;userSettings().profile.email=f.email;Object.assign(db.users.find(u=>u.id===activeUserId()),{name:f.name,email:f.email});persist();location.hash='/onboarding';return;}navigate('overview','user');return;}
 default:return;}
 persist();close();render();toast('Changes saved to your demo workspace.');
});
window.addEventListener('hashchange',()=>{close();parseRoute();render();window.scrollTo({top:0,behavior:'instant'});});
parseRoute();render();
